typedef struct {
   unsigned char *name;
   uint8_t flags;            // GRASPで定義されたフラグビット
   uint8_t loop_count;
   uint32_t value_size;      // 値のサイズ（バイト単位）
   cbor_mutable_data cbor_value;
                            // CBORバイト列（libcbor/cbor/data.h）
                } objective;
